function MiniSpark({ points, color }) {
  const w = 56, h = 22;
  const max = Math.max(...points), min = Math.min(...points);
  const sx = (i) => (i / (points.length - 1)) * w;
  const sy = (v) => h - ((v - min) / (max - min || 1)) * h;
  const d = points.map((p, i) => `${i === 0 ? "M" : "L"}${sx(i).toFixed(1)},${sy(p).toFixed(1)}`).join(" ");
  return <svg data-source="src/pages/WatchlistPage.jsx:23:9" width={w} height={h}><path data-source="src/pages/WatchlistPage.jsx:23:35" d={d} fill="none" stroke={color} strokeWidth="1.6" /></svg>;
}

