import React, { useEffect, useRef, useState } from "react";

export const EXIT_MS = 240;

export function cx(...values) {
  return values.filter(Boolean).join(" ");
}

export function useOverlayLifecycle(open, onOpenChange) {
  const [mounted, setMounted] = useState(open);
  const [state, setState] = useState(open ? "open" : "closed");
  const panelRef = useRef(null);
  const previousFocusRef = useRef(null);

  useEffect(() => {
    if (open) {
      setMounted(true);
      const frame = requestAnimationFrame(() => setState("open"));
      return () => cancelAnimationFrame(frame);
    }
    if (!mounted) return undefined;
    setState("closing");
    const timer = window.setTimeout(() => {
      setMounted(false);
      setState("closed");
    }, EXIT_MS);
    return () => window.clearTimeout(timer);
  }, [mounted, open]);

  useEffect(() => {
    if (!open) return undefined;
    previousFocusRef.current = document.activeElement;
    const frame = requestAnimationFrame(() => panelRef.current?.focus());
    const onKeyDown = (event) => {
      if (event.key === "Escape") onOpenChange(false);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => {
      cancelAnimationFrame(frame);
      document.removeEventListener("keydown", onKeyDown);
      previousFocusRef.current?.focus?.();
    };
  }, [onOpenChange, open]);

  return { mounted, panelRef, state };
}

export function OverlayLayer({ state, onOpenChange, closeOnBackdrop, centered, classNames, children }) {
  return (
    <div data-source="src/components/mobile/_overlay-core.jsx:50:4"
      className={cx(
        "absolute inset-0 z-[100]",
        centered ? "flex items-center justify-center p-6" : "flex items-end",
        classNames.root,
      )}
      data-mobile-overlay
      data-state={state}
      style={{ pointerEvents: state === "closing" ? "none" : "auto" }}
    >
      <button data-source="src/components/mobile/_overlay-core.jsx:60:6"
        type="button"
        className={cx("absolute inset-0 border-0 bg-black/40", classNames.backdrop)}
        data-slot="backdrop"
        aria-label="关闭"
        style={{ opacity: state === "closing" ? 0 : 1, transition: "opacity " + EXIT_MS + "ms ease" }}
        onClick={() => closeOnBackdrop && onOpenChange(false)}
      />
      {children}
    </div>
  );
}
