import React, { useState, useRef } from "react";
import { Sparkles, ChevronDown, ChevronUp, ThumbsUp, ThumbsDown, FileText, TrendingUp, MessageSquareText, Coins, Info, Clock, AlertTriangle, Link2, ShieldCheck } from "lucide-react";
import { MobileSheet } from "./mobile/index.js";

const DIM_META = {
  price: { label: "价格", Icon: TrendingUp, tint: "#2E5BFF" },
  news: { label: "消息", Icon: MessageSquareText, tint: "#7C4DFF" },
  fund: { label: "资金", Icon: Coins, tint: "#FF8A00" },
};

// 出处 chip
function SourceChip({ source, onOpen }) {
  return (
    <button data-source="src/components/DigestCard.jsx:14:4"
      onClick={() => onOpen(source)}
      className="mt-1.5 inline-flex items-center gap-1 rounded-lg border border-[#DCE3FF] bg-[#F3F6FF] px-2 py-[3px] text-[11px] font-medium text-[#2E5BFF] active:opacity-70"
    >
      <Link2 data-source="src/components/DigestCard.jsx:18:6" className="h-3 w-3" strokeWidth={2.2} />
      <span data-source="src/components/DigestCard.jsx:19:6" className="border-b border-dashed border-[#9FB4FF] pb-px">{source.tag}</span>
    </button>
  );
}

/**
 * DigestCard —— 今日解读卡片
 * props.data:
 *   headline           一句话结论
 *   tone               'calm-signal' | 'calm-safe' | 'volatile-news' | 'volatile-nonews' | 'high-risk'
 *   updatedAt          时间戳
 *   updatedFlag        是否显示"解读已更新"高亮
 *   changeNote         更新变化点文案（高亮块）
 *   attributions       [{ dim, text, source }]  三维归因（high-risk 时为空/仅事实）
 *   facts              [{ label, value }]  事实摘要
 *   opinions           [{ text, from }]    市场观点（可空）
 *   degraded           true 时不显示 AI 主观归因
 */
export default function DigestCard({ data }) {
  const [expanded, setExpanded] = useState(true);
  const [vote, setVote] = useState(null);
  const [sheetSource, setSheetSource] = useState(null);

  const toneBadge =
    data.tone === "high-risk"
      ? { text: "客观事实播报", bg: "bg-[#FFF4E6]", fg: "text-[#C25E00]", Icon: ShieldCheck }
      : { text: "AI 当日解读", bg: "bg-[#EEF2FF]", fg: "text-[#2E5BFF]", Icon: Sparkles };

  return (
    <div data-source="src/components/DigestCard.jsx:48:4" className="overflow-hidden rounded-2xl bg-white shadow-[0_4px_20px_rgba(26,29,36,0.06)]">
      {/* 顶部：胶囊标 + 时间戳 */}
      <div data-source="src/components/DigestCard.jsx:50:6" className="flex items-center justify-between px-4 pt-4">
        <span data-source="src/components/DigestCard.jsx:51:8" className={`inline-flex items-center gap-1 rounded-full ${toneBadge.bg} px-2.5 py-1 text-[12px] font-semibold ${toneBadge.fg}`}>
          <toneBadge.Icon data-source="src/components/DigestCard.jsx:52:10" className="h-3.5 w-3.5" strokeWidth={2.2} />
          {toneBadge.text}
        </span>
        <span data-source="src/components/DigestCard.jsx:55:8" className="flex items-center gap-1 text-[11px] text-[#8A9099]">
          <Clock data-source="src/components/DigestCard.jsx:56:10" className="h-3 w-3" strokeWidth={2} />
          {data.updatedAt}
        </span>
      </div>

      {/* 解读已更新高亮块 */}
      {data.updatedFlag && (
        <div data-source="src/components/DigestCard.jsx:63:8" className="mx-4 mt-3 flex items-start gap-2 rounded-xl border border-[#FFD8A8] bg-[#FFF7ED] px-3 py-2.5">
          <AlertTriangle data-source="src/components/DigestCard.jsx:64:10" className="mt-px h-4 w-4 shrink-0 text-[#FF8A00]" strokeWidth={2.2} />
          <div data-source="src/components/DigestCard.jsx:65:10" className="text-[12.5px] leading-snug text-[#8A4B00]">
            <span data-source="src/components/DigestCard.jsx:66:12" className="font-semibold">解读已更新　</span>
            {data.changeNote}
          </div>
        </div>
      )}

      {/* 一句话结论（金字塔顶） */}
      <div data-source="src/components/DigestCard.jsx:73:6" className="px-4 pt-3.5 pb-1">
        <p data-source="src/components/DigestCard.jsx:74:8" className="text-[18px] font-bold leading-[1.5] text-[#1A1D24]">{data.headline}</p>
      </div>

      {/* 三维归因 */}
      {!data.degraded && data.attributions?.length > 0 && (
        <div data-source="src/components/DigestCard.jsx:79:8" className="px-4 pt-2">
          <button data-source="src/components/DigestCard.jsx:80:10"
            onClick={() => setExpanded((v) => !v)}
            className="mb-2 flex w-full items-center justify-between text-[13px] font-semibold text-[#8A9099]"
          >
            <span data-source="src/components/DigestCard.jsx:84:12">为什么这么说 · 三维归因</span>
            {expanded ? <ChevronUp data-source="src/components/DigestCard.jsx:85:24" className="h-4 w-4" /> : <ChevronDown data-source="src/components/DigestCard.jsx:85:60" className="h-4 w-4" />}
          </button>
          {expanded && (
            <div data-source="src/components/DigestCard.jsx:88:12" className="space-y-2.5">
              {data.attributions.map((a, i) => {
                const meta = DIM_META[a.dim];
                return (
                  <div data-source="src/components/DigestCard.jsx:92:18" key={i} className="flex gap-2.5 rounded-xl bg-[#FAFBFC] p-3">
                    <span data-source="src/components/DigestCard.jsx:93:20"
                      className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg"
                      style={{ backgroundColor: meta.tint + "18" }}
                    >
                      <meta.Icon data-source="src/components/DigestCard.jsx:97:22" className="h-4 w-4" style={{ color: meta.tint }} strokeWidth={2.2} />
                    </span>
                    <div data-source="src/components/DigestCard.jsx:99:20" className="min-w-0 flex-1">
                      <span data-source="src/components/DigestCard.jsx:100:22" className="text-[12px] font-semibold" style={{ color: meta.tint }}>
                        {meta.label}
                      </span>
                      <p data-source="src/components/DigestCard.jsx:103:22" className="mt-0.5 text-[13.5px] leading-relaxed text-[#3D424D]">{a.text}</p>
                      {a.source && <SourceChip data-source="src/components/DigestCard.jsx:104:35" source={a.source} onOpen={setSheetSource} />}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* 降级态：仅公告原文链接（无 AI 主观归因） */}
      {data.degraded && data.degradedSources?.length > 0 && (
        <div data-source="src/components/DigestCard.jsx:116:8" className="px-4 pt-3">
          <div data-source="src/components/DigestCard.jsx:117:10" className="mb-2 text-[13px] font-semibold text-[#8A9099]">相关公告原文（客观事实）</div>
          <div data-source="src/components/DigestCard.jsx:118:10" className="space-y-2">
            {data.degradedSources.map((s, i) => (
              <button data-source="src/components/DigestCard.jsx:120:14"
                key={i}
                onClick={() => setSheetSource(s)}
                className="flex w-full items-start gap-2.5 rounded-xl border border-[#FFD8A8] bg-[#FFFBF5] p-3 text-left active:opacity-80"
              >
                <FileText data-source="src/components/DigestCard.jsx:125:16" className="mt-px h-4 w-4 shrink-0 text-[#FF8A00]" strokeWidth={2.2} />
                <div data-source="src/components/DigestCard.jsx:126:16" className="min-w-0 flex-1">
                  <p data-source="src/components/DigestCard.jsx:127:18" className="text-[13.5px] font-semibold leading-snug text-[#1A1D24]">{s.title}</p>
                  <p data-source="src/components/DigestCard.jsx:128:18" className="mt-0.5 text-[11px] text-[#8A9099]">{s.publisher} · {s.time}</p>
                </div>
                <Link2 data-source="src/components/DigestCard.jsx:130:16" className="mt-0.5 h-3.5 w-3.5 shrink-0 text-[#FF8A00]" />
              </button>
            ))}
          </div>
        </div>
      )}

      {/* 事实摘要模块 */}
      {data.facts?.length > 0 && (
        <div data-source="src/components/DigestCard.jsx:139:8" className="mx-4 mt-3 rounded-xl border border-[#DCE3FF] bg-[#EEF2FF] p-3">
          <div data-source="src/components/DigestCard.jsx:140:10" className="mb-2 flex items-center gap-1.5 text-[12.5px] font-bold text-[#2E5BFF]">
            <FileText data-source="src/components/DigestCard.jsx:141:12" className="h-3.5 w-3.5" strokeWidth={2.4} />
            事实摘要 · 客观数据
          </div>
          <div data-source="src/components/DigestCard.jsx:144:10" className="grid grid-cols-2 gap-x-3 gap-y-2">
            {data.facts.map((f, i) => (
              <div data-source="src/components/DigestCard.jsx:146:14" key={i} className="flex flex-col">
                <span data-source="src/components/DigestCard.jsx:147:16" className="text-[11px] text-[#6B7BB5]">{f.label}</span>
                <span data-source="src/components/DigestCard.jsx:148:16" className="text-[14px] font-semibold text-[#1A1D24]">{f.value}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 市场观点模块（弱化） */}
      {data.opinions?.length > 0 && (
        <div data-source="src/components/DigestCard.jsx:157:8" className="mx-4 mt-2.5 rounded-xl border border-[#EDEFF2] bg-[#F7F8FA] p-3">
          <div data-source="src/components/DigestCard.jsx:158:10" className="mb-1.5 flex items-center gap-1.5 text-[12px] font-semibold text-[#9AA0A9]">
            <MessageSquareText data-source="src/components/DigestCard.jsx:159:12" className="h-3.5 w-3.5" strokeWidth={2} />
            市场观点 · 仅供参考
          </div>
          {data.opinions.map((o, i) => (
            <div data-source="src/components/DigestCard.jsx:163:12" key={i} className="mt-1">
              <p data-source="src/components/DigestCard.jsx:164:14" className="text-[12.5px] leading-relaxed text-[#8A9099]">「{o.text}」</p>
              <span data-source="src/components/DigestCard.jsx:165:14" className="text-[11px] text-[#B4B9C2]">网友讨论 · 来源：{o.from}</span>
            </div>
          ))}
        </div>
      )}

      {/* 反馈 + 免责 */}
      <div data-source="src/components/DigestCard.jsx:172:6" className="mt-3.5 border-t border-[#F0F1F3] px-4 py-3">
        <div data-source="src/components/DigestCard.jsx:173:8" className="flex items-center justify-between">
          <span data-source="src/components/DigestCard.jsx:174:10" className="text-[12px] text-[#8A9099]">这份解读对你有用吗？</span>
          <div data-source="src/components/DigestCard.jsx:175:10" className="flex gap-2">
            <button data-source="src/components/DigestCard.jsx:176:12"
              onClick={() => setVote("up")}
              className={`inline-flex items-center gap-1 rounded-full border px-3 py-1 text-[12px] font-medium transition ${
                vote === "up" ? "border-[#17B26A] bg-[#E7F8F0] text-[#17B26A]" : "border-[#E3E5E9] text-[#6B7079]"
              }`}
            >
              <ThumbsUp data-source="src/components/DigestCard.jsx:182:14" className="h-3.5 w-3.5" strokeWidth={2.2} />
              有用
            </button>
            <button data-source="src/components/DigestCard.jsx:185:12"
              onClick={() => setVote("down")}
              className={`inline-flex items-center gap-1 rounded-full border px-3 py-1 text-[12px] font-medium transition ${
                vote === "down" ? "border-[#F5453E] bg-[#FDECEB] text-[#F5453E]" : "border-[#E3E5E9] text-[#6B7079]"
              }`}
            >
              <ThumbsDown data-source="src/components/DigestCard.jsx:191:14" className="h-3.5 w-3.5" strokeWidth={2.2} />
              没用
            </button>
          </div>
        </div>
        {vote && (
          <p data-source="src/components/DigestCard.jsx:197:10" className="mt-2 text-[11.5px] text-[#17B26A]">
            {vote === "up" ? "感谢反馈，我们会继续优化解读质量 🙌" : "已记录，负反馈会触发人工复核"}
          </p>
        )}
        <p data-source="src/components/DigestCard.jsx:201:8" className="mt-2.5 flex items-start gap-1 text-[11px] leading-relaxed text-[#B4B9C2]">
          <Info data-source="src/components/DigestCard.jsx:202:10" className="mt-px h-3 w-3 shrink-0" strokeWidth={2} />
          本内容由 AI 基于平台公开数据生成，仅对已发生的情况作客观说明，不构成任何投资建议。
        </p>
      </div>

      {/* 出处原文 Sheet */}
      <MobileSheet data-source="src/components/DigestCard.jsx:208:6" open={!!sheetSource} onOpenChange={(o) => !o && setSheetSource(null)} title="原始来源">
        {sheetSource && (
          <div data-source="src/components/DigestCard.jsx:210:10" className="px-1 pb-2">
            <div data-source="src/components/DigestCard.jsx:211:12" className="mb-3 flex items-center gap-2">
              <span data-source="src/components/DigestCard.jsx:212:14" className={`rounded-md px-2 py-0.5 text-[11px] font-semibold ${
                sheetSource.official ? "bg-[#EEF2FF] text-[#2E5BFF]" : "bg-[#F2F3F5] text-[#8A9099]"
              }`}>
                {sheetSource.official ? "官方信源" : "社区讨论"}
              </span>
              <span data-source="src/components/DigestCard.jsx:217:14" className="text-[12px] text-[#8A9099]">{sheetSource.time}</span>
            </div>
            <h3 data-source="src/components/DigestCard.jsx:219:12" className="text-[16px] font-bold leading-snug text-[#1A1D24]">{sheetSource.title}</h3>
            <p data-source="src/components/DigestCard.jsx:220:12" className="mt-1 text-[12px] text-[#8A9099]">{sheetSource.publisher}</p>
            <p data-source="src/components/DigestCard.jsx:221:12" className="mt-3 text-[13.5px] leading-relaxed text-[#3D424D]">{sheetSource.body}</p>
            {!sheetSource.official && (
              <p data-source="src/components/DigestCard.jsx:223:14" className="mt-3 rounded-lg bg-[#FFF7ED] px-3 py-2 text-[11.5px] leading-relaxed text-[#8A4B00]">
                该内容为社区/搜索来源，已降级为"网友讨论"，不参与主归因，请注意甄别。
              </p>
            )}
          </div>
        )}
      </MobileSheet>
    </div>
  );
}
