/**
 * 设备框随页面高度缩放。
 *
 * 基准高度是设计稿中设备框的固定逻辑高度（874px），只按视口高度折算。不能读取
 * 已经应用 CSS zoom 的元素尺寸再反推基准：横向拖动引发的布局回流会影响这类测量，
 * 进而把与高度无关的变化错误传回 zoom。窄屏只在跨越布局断点时读取一次顶部流程栏
 * 的静态高度，为设备框留出下方安全区；普通横向拖动不重算。
 */
function useDeviceFrameZoom(panelRef) {
  const zoomRef = useRef(DEVICE_FRAME_ZOOM_BASE);
  const viewportRef = useRef("");
  const [zoom, setZoom] = useState(DEVICE_FRAME_ZOOM_BASE);

  useEffect(() => {
    let frameId;
    const syncZoom = () => {
      cancelAnimationFrame(frameId);
      frameId = requestAnimationFrame(() => {
        const viewportHeight = window.innerHeight;
        if (!viewportHeight) return;
        const isMobileLayout = window.matchMedia("(max-width: 640px)").matches;
        // 横向拖拽也会派发 resize；只有高度变化或跨越 640px 布局断点才重新计算。
        const viewportKey = viewportHeight + ":" + isMobileLayout;
        if (viewportKey === viewportRef.current) return;
        viewportRef.current = viewportKey;
        const panelHeight = panelRef.current?.offsetHeight || MOBILE_FLOW_PANEL_FALLBACK_HEIGHT;
        const availableHeight = isMobileLayout
          ? Math.max(viewportHeight - panelHeight - MOBILE_FLOW_PANEL_GAP - STAGE_SIDE_INSET, 0)
          : viewportHeight;
        const zoomBase = isMobileLayout
          ? MOBILE_DEVICE_FRAME_ZOOM_BASE
          : DEVICE_FRAME_ZOOM_BASE;

        const nextZoom = Math.min(
          (availableHeight / DEVICE_FRAME_HEIGHT) * zoomBase,
          DEVICE_FRAME_MAX_ZOOM,
        );
        if (Math.abs(zoomRef.current - nextZoom) < 0.001) return;
        zoomRef.current = nextZoom;
        setZoom(nextZoom);
      });
    };

    syncZoom();
    window.addEventListener("resize", syncZoom);
    return () => {
      cancelAnimationFrame(frameId);
      window.removeEventListener("resize", syncZoom);
    };
  }, [panelRef]);

  return zoom;
}

