/**
 * 嵌入飞书文档 HTML Box 小组件时的宿主高度（px）。
 *
 * 为什么要固定高度而不是让它自适应：HTML Box 的 auto 模式下宿主高度由内容高度决定，
 * 而 harness 生成的 index.html 写死了 html,body,#root 的 height:100%——内容高度反过来
 * 又依赖宿主高度，互相依赖会让高度塌陷成 0。所以嵌入时给一个确定值，撑住这条链。
 *
 * 640px 的来由：设备框 874px 逻辑高度按 zoom 缩放后，640px 能让它显示到约 0.72 倍
 * （约 630px 高），是"看得清内容"和"不过度占据文档版面"的折中。
 */
const EMBED_HOST_HEIGHT = 640;

/**
 * 检测到飞书文档 HTML Box 宿主时，声明 auto 高度模式并把宿主高度刷到 EMBED_HOST_HEIGHT。
 *
 * 判定依据是宿主 API window.magic 是否存在，**不能**用「是否在 iframe 内」——
 * 预览链接经常被套在别的 iframe 里打开（IDE / Flux 内嵌浏览器就是这样），那些场景
 * 应当照常按视口自适应铺满；按 iframe 判会把它们误当成 HTML Box、高度钉死 640px，
 * 底部空出一大片。只有真正的 HTML Box 宿主才会注入 magic。
 *
 * magic 可能比页面脚本晚就绪，所以要轮询探测；探测不到就一直是非嵌入模式（自适应）。
 *
 * 命中后做两件事：
 * ① 注入 <meta name="html-box-height-mode" content="auto">，告诉宿主按文档流算高度；
 * ② 把根容器高度钉成 640px，再调 magic.updateHeight() 让宿主按新高度刷新。
 */
function useEmbedHostHeight() {
  const [embedded, setEmbedded] = useState(false);

  useEffect(() => {
    let done = false;
    let tries = 0;

    const pickRefresh = () => {
      const magic = window.magic;
      const fn = magic?.updateHeight || magic?.refreshHeight || magic?.resize;
      return typeof fn === "function" ? () => fn.call(magic) : undefined;
    };

    const apply = () => {
      const refresh = pickRefresh();
      if (!refresh) return false;

      setEmbedded(true);

      if (!document.querySelector('meta[name="html-box-height-mode"]')) {
        const meta = document.createElement("meta");
        meta.name = "html-box-height-mode";
        meta.content = "auto";
        document.head.appendChild(meta);
      }

      // index.html 由 harness 生成（禁止改），其 html/body/#root 是 height:100%；
      // 这里覆写成固定值，auto 模式才有确定的内容高度可算。
      for (const el of [document.documentElement, document.body]) {
        el.style.height = EMBED_HOST_HEIGHT + "px";
      }
      const root = document.getElementById("root");
      if (root) root.style.height = EMBED_HOST_HEIGHT + "px";

      refresh();
      return true;
    };

    if (apply()) return;
    const timer = setInterval(() => {
      if (done) return;
      // 探测约 4s（20 * 200ms）。到点还没有 magic 就认定不是 HTML Box，保持自适应。
      if (apply() || ++tries > 20) {
        done = true;
        clearInterval(timer);
      }
    }, 200);
    return () => clearInterval(timer);
  }, []);

  return embedded;
}

/**
 * 圈选 SDK 的消息契约，来自 packages/selection-sdk/src/types.ts。
 *
 * 这里认的是 **-host 后缀**那个：宿主 → SDK 方向。SDK → 宿主方向的消息
 * （source 为 "@rdservices/selection-sdk"，含 mode-change）走的是
 * window.parent.postMessage，只发给外层平台页面，本原型这一层收不到。
 * 实测到达 iframe 内的就是 host 方向的 start / stop。
 */
const SELECTION_HOST_SOURCE = "@rdservices/selection-sdk-host";

/**
 * 监听宿主平台的圈选（元素拾取）开关。
 *
 * 平台页面把本原型嵌在 iframe 里，用户开启圈选后要在原型上点选元素做标注。这期间
 * 任何切页都会让标注脱离上下文——用户正框着 A 页的某个按钮，页面却翻到了 B 页，
 * 于是标注落到了错误的元素上，甚至框选中途目标直接消失。所以圈选期间冻结场景切换。
 *
 * 契约（HostMessageType，见 selection-sdk 的 auto.ts 各 onHostMessage 分支）：
 * - start   → startPicking()，圈选开启
 * - stop    → stopPicking()，圈选关闭
 * - destroy → 整个 SDK 销毁，圈选自然结束，同样要解冻
 * - update-config 只改主题，与冻结无关，不响应
 *
 * 未知 type 一律不改状态：宁可维持现状，也不要因为契约将来多出一个消息就误判成
 * 「圈选已关闭」而放开切页——那正是本函数要防的事。
 */
function useSelectionPicking() {
  const [picking, setPicking] = useState(false);

  useEffect(() => {
    const onMessage = (e) => {
      const data = e.data;
      if (!data || data.source !== SELECTION_HOST_SOURCE) return;
      if (data.type === "start") setPicking(true);
      else if (data.type === "stop" || data.type === "destroy") setPicking(false);
    };
    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, []);

  return picking;
}

export default function PrototypeShell() {
  const [idx, setIdx] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [tick, setTick] = useState(0);
  const timer = useRef(null);
  const flowPanelRef = useRef(null);
  const embedded = useEmbedHostHeight();
  const picking = useSelectionPicking();

  const go = useCallback((next) => {
    setIdx(next);
    setTick((t) => t + 1);
  }, []);

  // 圈选进行中冻结一切场景切换。pick 是所有切页路径的唯一出口（侧栏点选、
  // __goToScene 全汇到这里），在此拦一道就等于全挡住了。
  //
  // 用 ref 而不是直接读 picking：pick 被 useCallback 缓存并透给一堆子组件，把 picking
  // 放进依赖会让它每次开关圈选都换新引用，白连带整棵控件树重渲染。
  const pickingRef = useRef(false);
  useEffect(() => { pickingRef.current = picking; }, [picking]);

  const pick = useCallback((next) => {
    if (pickingRef.current) return;
    setPlaying(false);
    go(next);
  }, [go]);

  // playing 要给 __goToScene 读，但那个 effect 不能挂 playing 依赖——每次播放状态变化
  // 都重注册一次全局函数，且页面在渲染间隙调用会读到过期的 playing。用 ref 取当下值。
  const playingRef = useRef(false);
  useEffect(() => { playingRef.current = playing; }, [playing]);

  // 页面内部的行动按钮通过 window.__goToScene("<sceneId>") 驱动跨场景跳转，
  // 这样原型不止能用顶部导航切页，还能按真实流程一步步走下去。
  //
  // 自动演播进行中一律忽略这里的跳转请求：页面自己的定时器（开屏广告倒计时、
  // 启动页延时进主页之类）会和演播的 waitAfterMs 赛跑，谁先到谁说话。实测开屏页
  // 3s 倒计时跑赢了该页 3500ms 的 waitAfterMs，于是 __goToScene("foryou") 抢先执行，
  // 直接从第 1 页跳到第 3 页——中间那页被整个跳过，而且 pick 顺带 setPlaying(false)
  // 把演播也停了。演播的语义是「按 SCENES 顺序走一遍全部页面」，页面自发的跳转在
  // 这个语义下只能是干扰，忽略掉才是对的。
  //
  // 只挡演播期间「页面发起」的跳转：外壳 UI 的翻页/侧栏点选走的是 pick，不经这里，
  // 用户手动操作照旧生效（并按原有语义停播）。不去区分「定时器 vs 页面内点击」——
  // 那个区分靠 navigator.userActivation 之类的信号做不可靠（用户刚点过 ▶ 就有几秒
  // 激活窗口，正好会把倒计时误判成手动点击，恰恰破在要修的这个场景上）。
  useEffect(() => {
    window.__goToScene = (sceneId) => {
      if (playingRef.current) return;
      const i = SCENES.findIndex((s) => s.id === sceneId);
      if (i >= 0) pick(i);
    };
    return () => { delete window.__goToScene; };
  }, [pick]);

  // 演播推进走 go、不经 pick，所以圈选的闸门要在这里另设一道：picking 时直接不排
  // 定时器（依赖数组带上 picking，开启圈选会重跑本 effect 并 clearTimeout 掉在途的那个）。
  //
  // 这里刻意不改 playing：圈选结束后本 effect 再次重跑，playing 仍为 true 便自动接着
  // 演播下去，用户不用重新点 ▶。相当于圈选期间「挂起」而非「停止」。
  useEffect(() => {
    if (!playing || picking) return;
    const nextIdx = idx + 1;
    if (nextIdx >= SCENES.length) {
      timer.current = setTimeout(() => setPlaying(false), 1600);
      return () => clearTimeout(timer.current);
    }
    const wait = SCENES[nextIdx].waitAfterMs || DEFAULT_AUTOPLAY_DELAY;
    timer.current = setTimeout(() => go(nextIdx), wait);
    return () => clearTimeout(timer.current);
  }, [playing, picking, idx, go]);

  const togglePlay = () => {
    // 圈选期间不起播。这一支会调 go(0) 回到首页重播，绕过了 pick 的闸门。
    if (picking) return;
    if (idx >= SCENES.length - 1) {
      go(0);
      setTimeout(() => setPlaying(true), 60);
    } else {
      setPlaying((p) => !p);
    }
  };

  const cur = SCENES[idx];
  const Comp = cur.Comp;
  return (
    <div data-source="src/index.jsx:491:4"
      className="flex flex-col items-center overflow-hidden w-full bg-[#FAFAFA] font-sans"
      style={{
        height: embedded ? EMBED_HOST_HEIGHT : "100vh",
        // 设计稿「装饰而已」点阵：直径 3px 的圆点、#888888 6%、水平/垂直间距 19px 的规律网格。
        // 用 radial-gradient 平铺复刻，叠在 #FAFAFA 底色上（backgroundColor 与 backgroundImage
        // 各自独立，圆点画在纯色之上）。1.5px 半径 = 3px 直径。
        backgroundImage: "radial-gradient(circle at 1.5px 1.5px, rgba(136,136,136,0.06) 1.5px, transparent 1.6px)",
        backgroundSize: "19px 19px",
      }}
    >
      <style data-source="src/index.jsx:502:6">{`@keyframes sceneIn{from{opacity:.4;transform:translateY(6px) scale(.99)}to{opacity:1;transform:none}}`}</style>

      {/*
        圈选期间说明为什么切页被冻结。只在 picking 时渲染，常态不占任何空间。
        按钮的 disabled 只表达"不能点"、不解释原因，光靠它用户会以为原型坏了。

        作为整屏第一条信息钉在最顶上。不需要 sticky：外层是固定高度 +
        overflow-hidden 的 flex 列，父级不产生滚动（滚动只发生在页面组件内部），
        本条作为第一个 flex 子项就已经钉在最顶上。
      */}
      {picking && (
        <div data-source="src/index.jsx:513:8" className="w-full shrink-0 bg-amber-50 border-b border-amber-200 px-4 py-1 text-center text-[11px] text-amber-700">
          圈选中 · 已暂停页面切换与自动演播，关闭圈选后恢复
        </div>
      )}

      {/*
        宽屏时设备框居左、流程说明栏在右；小于等于 640px 时，流程栏移到设备框顶部，
        步骤保持单行并横向滚动。设备框按页面高度折算 zoom，舞台四周至少保留 32px
        安全距离。
      */}
      <div data-source="src/index.jsx:523:6"
        className="mobile-flow-stage flex-1 min-h-0 w-full flex items-center justify-center gap-[clamp(16px,3vw,32px)]"
        style={{ paddingInline: STAGE_SIDE_INSET, paddingBlock: STAGE_SIDE_INSET }}
      >
        <DeviceFrame data-source="src/index.jsx:527:8" transition={tick} panelRef={flowPanelRef}>
          <Comp data-source="src/index.jsx:528:10" />
        </DeviceFrame>
        <FlowPanel data-source="src/index.jsx:530:8"
          scenes={SCENES}
          idx={idx}
          onPick={pick}
          title={APP_TITLE}
          playing={playing}
          onTogglePlay={togglePlay}
          picking={picking}
          panelRef={flowPanelRef}
        />
      </div>
    </div>
  );
}
