import React from "react";
import { ChevronLeft, Star, MoreHorizontal, Search } from "lucide-react";
import StatusBar from "./StatusBar.jsx";
import Sparkline from "./Sparkline.jsx";

const UP = "#F5453E";
const DOWN = "#17B26A";

// 详情页通用外壳：顶栏 + 行情头 + 走势图，children 为解读卡片区
export default function StockDetailShell({ stock, children, footer }) {
  const isUp = stock.change >= 0;
  const c = isUp ? UP : DOWN;
  const sign = isUp ? "+" : "";

  return (
    <div data-source="src/components/StockDetailShell.jsx:16:4" className="flex h-full flex-col bg-[#F4F5F7]">
      <div data-source="src/components/StockDetailShell.jsx:17:6" className="shrink-0 bg-white">
        <StatusBar data-source="src/components/StockDetailShell.jsx:18:8" dark={false} />
        {/* 顶栏 */}
        <div data-source="src/components/StockDetailShell.jsx:20:8" className="flex items-center justify-between px-3 pb-2">
          <button data-source="src/components/StockDetailShell.jsx:21:10" onClick={() => window.__goToScene?.("watchlist")} className="flex h-9 w-9 items-center justify-center active:opacity-60">
            <ChevronLeft data-source="src/components/StockDetailShell.jsx:22:12" className="h-6 w-6 text-[#1A1D24]" strokeWidth={2.2} />
          </button>
          <div data-source="src/components/StockDetailShell.jsx:24:10" className="flex flex-col items-center">
            <span data-source="src/components/StockDetailShell.jsx:25:12" className="text-[16px] font-bold leading-tight text-[#1A1D24]">{stock.name}</span>
            <span data-source="src/components/StockDetailShell.jsx:26:12" className="text-[11px] text-[#8A9099]">{stock.code}</span>
          </div>
          <div data-source="src/components/StockDetailShell.jsx:28:10" className="flex items-center gap-1">
            <button data-source="src/components/StockDetailShell.jsx:29:12" className="flex h-9 w-9 items-center justify-center active:opacity-60">
              <Search data-source="src/components/StockDetailShell.jsx:30:14" className="h-5 w-5 text-[#4A4F58]" strokeWidth={2} />
            </button>
            <button data-source="src/components/StockDetailShell.jsx:32:12" className="flex h-9 w-9 items-center justify-center active:opacity-60">
              <MoreHorizontal data-source="src/components/StockDetailShell.jsx:33:14" className="h-5 w-5 text-[#4A4F58]" strokeWidth={2} />
            </button>
          </div>
        </div>
      </div>

      {/* 行情头 + 走势图 */}
      <div data-source="src/components/StockDetailShell.jsx:40:6" className="shrink-0 bg-white px-4 pb-3">
        <div data-source="src/components/StockDetailShell.jsx:41:8" className="flex items-end gap-3">
          <span data-source="src/components/StockDetailShell.jsx:42:10" className="text-[34px] font-bold leading-none" style={{ color: c }}>{stock.price}</span>
          <div data-source="src/components/StockDetailShell.jsx:43:10" className="mb-1 flex flex-col text-[14px] font-semibold" style={{ color: c }}>
            <span data-source="src/components/StockDetailShell.jsx:44:12">{sign}{stock.diff}</span>
            <span data-source="src/components/StockDetailShell.jsx:45:12">{sign}{stock.change}%</span>
          </div>
        </div>
        <div data-source="src/components/StockDetailShell.jsx:48:8" className="mt-3">
          <Sparkline data-source="src/components/StockDetailShell.jsx:49:10"
            points={stock.points}
            color={c}
            fill={isUp ? "rgba(245,69,62,0.12)" : "rgba(23,178,106,0.12)"}
            prevClose={stock.prevClose}
          />
        </div>
        <div data-source="src/components/StockDetailShell.jsx:56:8" className="mt-2 flex justify-between text-[11px] text-[#8A9099]">
          <span data-source="src/components/StockDetailShell.jsx:57:10">09:30</span><span data-source="src/components/StockDetailShell.jsx:57:28">11:30/13:00</span><span data-source="src/components/StockDetailShell.jsx:57:52">15:00</span>
        </div>
        {/* 关键指标条 */}
        <div data-source="src/components/StockDetailShell.jsx:60:8" className="mt-3 grid grid-cols-4 gap-1 rounded-xl bg-[#FAFBFC] py-2.5 text-center">
          {stock.stats.map((s, i) => (
            <div data-source="src/components/StockDetailShell.jsx:62:12" key={i} className="flex flex-col">
              <span data-source="src/components/StockDetailShell.jsx:63:14" className="text-[13px] font-semibold text-[#1A1D24]">{s.v}</span>
              <span data-source="src/components/StockDetailShell.jsx:64:14" className="mt-0.5 text-[10.5px] text-[#8A9099]">{s.k}</span>
            </div>
          ))}
        </div>
      </div>

      {/* 滚动内容区 */}
      <div data-source="src/components/StockDetailShell.jsx:71:6" className="min-h-0 flex-1 overflow-y-auto px-3.5 pb-4 pt-3">
        {children}
        {footer}
      </div>
    </div>
  );
}
