import React from "react";

// 简易分时/走势线图（SVG 自绘）。points: 0-100 归一化数值数组。
export default function Sparkline({ points, color = "#F5453E", fill = "rgba(245,69,62,0.10)", prevClose = 50, height = 130 }) {
  const w = 340;
  const h = height;
  const n = points.length;
  const max = Math.max(...points, prevClose);
  const min = Math.min(...points, prevClose);
  const pad = (max - min) * 0.15 || 1;
  const top = max + pad;
  const bot = min - pad;
  const scaleY = (v) => h - ((v - bot) / (top - bot)) * h;
  const scaleX = (i) => (i / (n - 1)) * w;

  const linePath = points.map((p, i) => `${i === 0 ? "M" : "L"}${scaleX(i).toFixed(1)},${scaleY(p).toFixed(1)}`).join(" ");
  const areaPath = `${linePath} L${w},${h} L0,${h} Z`;
  const prevY = scaleY(prevClose);

  return (
    <svg data-source="src/components/Sparkline.jsx:21:4" viewBox={`0 0 ${w} ${h}`} width="100%" height={h} preserveAspectRatio="none" className="block">
      <defs data-source="src/components/Sparkline.jsx:22:6">
        <linearGradient data-source="src/components/Sparkline.jsx:23:8" id={`grad-${color.replace("#", "")}`} x1="0" y1="0" x2="0" y2="1">
          <stop data-source="src/components/Sparkline.jsx:24:10" offset="0%" stopColor={fill} />
          <stop data-source="src/components/Sparkline.jsx:25:10" offset="100%" stopColor="rgba(255,255,255,0)" />
        </linearGradient>
      </defs>
      {/* 昨收虚线 */}
      <line data-source="src/components/Sparkline.jsx:29:6" x1="0" y1={prevY} x2={w} y2={prevY} stroke="#C9CDD4" strokeWidth="1" strokeDasharray="3 3" />
      <path data-source="src/components/Sparkline.jsx:30:6" d={areaPath} fill={`url(#grad-${color.replace("#", "")})`} />
      <path data-source="src/components/Sparkline.jsx:31:6" d={linePath} fill="none" stroke={color} strokeWidth="1.8" strokeLinejoin="round" />
    </svg>
  );
}
