import React, { useId, useRef, useState } from "react";
import { EXIT_MS, cx, OverlayLayer, useOverlayLifecycle } from "./_overlay-core.jsx";

export default function MobileSheet({
  open, onOpenChange, title, children, closeOnBackdrop = true, closeThreshold = 88,
  className = "", classNames = {},
}) {
  const { mounted, panelRef, state } = useOverlayLifecycle(open, onOpenChange);
  const [dragY, setDragY] = useState(0);
  const dragStartRef = useRef(null);
  const titleId = useId();
  if (!mounted) return null;

  const endDrag = () => {
    if (dragY > closeThreshold) onOpenChange(false);
    dragStartRef.current = null;
    setDragY(0);
  };

  return (
    <OverlayLayer data-source="src/components/mobile/MobileSheet.jsx:21:4" state={state} onOpenChange={onOpenChange} closeOnBackdrop={closeOnBackdrop} centered={false} classNames={classNames}>
      <section data-source="src/components/mobile/MobileSheet.jsx:22:6"
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        tabIndex={-1}
        className={cx(
          "relative max-h-[92%] w-full rounded-t-[24px] outline-none",
          className || "bg-white text-zinc-900 shadow-[0_-12px_40px_rgba(0,0,0,0.18)]",
          classNames.panel,
        )}
        data-slot="panel"
        style={{
          transform: "translate3d(0, " + (state === "closing" ? "105%" : dragY + "px") + ", 0)",
          transition: "transform " + EXIT_MS + "ms cubic-bezier(.16,1,.3,1)",
        }}
      >
        <div data-source="src/components/mobile/MobileSheet.jsx:39:8"
          className={cx("flex h-6 touch-none items-center justify-center", classNames.handleArea)}
          data-slot="handle-area"
          onPointerDown={(event) => { dragStartRef.current = event.clientY; event.currentTarget.setPointerCapture(event.pointerId); }}
          onPointerMove={(event) => dragStartRef.current !== null && setDragY(Math.max(0, event.clientY - dragStartRef.current))}
          onPointerUp={endDrag}
          onPointerCancel={endDrag}
        >
          <span data-source="src/components/mobile/MobileSheet.jsx:47:10" className={cx("h-1 w-9 rounded-full bg-current opacity-25", classNames.handle)} data-slot="handle" />
        </div>
        {title ? <h2 data-source="src/components/mobile/MobileSheet.jsx:49:17" id={titleId} className={cx("sr-only", classNames.title)} data-slot="title">{title}</h2> : null}
        {children}
      </section>
    </OverlayLayer>
  );
}
